def solve(D_in, D_out):
    H=len(D_in); W=len(D_in[0]); out=np.array(D_out)
    best=None
    for sign in (1,-1):
        for p in range(2,W+1):
            for t in range(p):
                # key = (c + sign*t*r) % p
                ok=True; M={}
                for r in range(H):
                    for c in range(W):
                        k=(c+sign*t*r)%p
                        v=out[r][c]
                        if k in M and M[k]!=v: ok=False;break
                        M[k]=v
                    if not ok:break
                if ok:
                    # reconstruct full grid with this tile and compare to output fully
                    pred=[[M[(c+sign*t*r)%p] for c in range(W)] for r in range(H)]
                    mism=sum(1 for r in range(H) for c in range(W) if pred[r][c]!=out[r][c])
                    score=(mism,abs(sign)*t,p)
                    if best is None or score<best[0]: best=(score,M,t,sign,p)
    sc,M,t,sign,p=best
    return (sc,t,sign,p),M

